package org.achievementlabs.mobile;
import android.app.*;import android.os.*;import android.content.*;import android.webkit.*;import android.view.*;import android.widget.*;
public final class LoginActivity extends Activity {
 WebView browser;OAuth flow;boolean done;
 @Override public void onCreate(Bundle b){super.onCreate(b);try{flow=new OAuth();LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);Button cancel=new Button(this);cancel.setText("Cancel Microsoft sign-in");cancel.setOnClickListener(v->finish());root.addView(cancel);browser=new WebView(this);root.addView(browser,new LinearLayout.LayoutParams(-1,0,1));setContentView(root);browser.getSettings().setJavaScriptEnabled(true);browser.getSettings().setAllowFileAccess(false);browser.getSettings().setAllowContentAccess(false);browser.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){String url=r.getUrl().toString();if(url.startsWith(OAuth.REDIRECT)){complete(url);return true;}return !"https".equals(r.getUrl().getScheme());}@Override public void onPageStarted(WebView view,String url,android.graphics.Bitmap icon){if(url.startsWith(OAuth.REDIRECT))complete(url);}});browser.loadUrl(flow.start());}catch(Exception e){new AlertDialog.Builder(this).setMessage("Could not start Microsoft sign-in.").setPositiveButton("Close",(d,w)->finish()).show();}}
 void complete(String url){if(done)return;try{flow.validate(url);}catch(Exception e){new AlertDialog.Builder(this).setMessage("The Microsoft redirect could not be validated. Start sign-in again.").setPositiveButton("Close",(d,w)->finish()).show();return;}done=true;browser.stopLoading();setContentView(new ProgressBar(this));new Thread(()->{try{org.json.JSONObject a=flow.exchange(url);MainActivity.pendingLogin=a;runOnUiThread(()->{setResult(RESULT_OK);finish();});}catch(Exception e){runOnUiThread(()->new AlertDialog.Builder(this).setMessage("Sign-in failed. Try the PC QR route or start again.").setPositiveButton("Close",(d,w)->finish()).show());}}).start();}
 @Override protected void onDestroy(){if(browser!=null){browser.stopLoading();browser.destroy();}super.onDestroy();}
}
